18	class InMemoryTaskTransportTest {
19	
20	    @Test
21	    void subscribedListenerReceivesPublishedEvents() {
22	        InMemoryTaskTransport transport = new InMemoryTaskTransport();
23	        List<TaskEvent> received = new ArrayList<>();
24	        transport.subscribe(received::add);
25	
26	        transport.publish(event(0, TaskEventType.STARTED));
27	        transport.publish(event(1, TaskEventType.COMPLETED));
28	
29	        assertThat(received)
30	                .extracting(TaskEvent::type)
31	                .containsExactly(TaskEventType.STARTED, TaskEventType.COMPLETED);
32	    }
33	
34	    @Test
35	    void everySubscribedListenerReceivesTheEvent() {
36	        InMemoryTaskTransport transport = new InMemoryTaskTransport();
37	        List<TaskEvent> firstInbox = new ArrayList<>();
38	        List<TaskEvent> secondInbox = new ArrayList<>();
39	        transport.subscribe(firstInbox::add);
40	        transport.subscribe(secondInbox::add);
41	
42	        transport.publish(event(0, TaskEventType.STARTED));
43	
44	        assertThat(firstInbox).hasSize(1);
45	        assertThat(secondInbox).hasSize(1);
46	    }
47	
48	    @Test
49	    void unsubscribedListenerStopsReceivingEvents() {
50	        InMemoryTaskTransport transport = new InMemoryTaskTransport();
51	        List<TaskEvent> received = new ArrayList<>();
52	        TaskListener listener = received::add;
53	        transport.subscribe(listener);
54	
55	        transport.publish(event(0, TaskEventType.STARTED));
56	        transport.unsubscribe(listener);
57	        transport.publish(event(1, TaskEventType.COMPLETED));
58	
59	        assertThat(received)
60	                .extracting(TaskEvent::type)
61	                .containsExactly(TaskEventType.STARTED);
62	    }
63	
64	    @Test
65	    void lateSubscriberDoesNotReceivePastEvents() {
66	        InMemoryTaskTransport transport = new InMemoryTaskTransport();
67	
68	        transport.publish(event(0, TaskEventType.STARTED));
69	        List<TaskEvent> received = new ArrayList<>();
70	        transport.subscribe(received::add);
71	
72	        assertThat(received).isEmpty();
73	    }
74	
75	    @Test
76	    void publishPropagatesListenerException() {
77	        InMemoryTaskTransport transport = new InMemoryTaskTransport();
78	        transport.subscribe(received -> {
79	            throw new IllegalStateException("listener failed");
80	        });
81	
82	        assertThatExceptionOfType(IllegalStateException.class)
83	                .isThrownBy(() -> transport.publish(event(0, TaskEventType.STARTED)))
84	                .withMessageContaining("listener failed");
85	    }
